	'k665b7ce9' => 'Les derniers paiements sont encaissés, les listes de chambres finalisées et les accompagnateurs briefés.',
	'k4e8db176' => 'Sur la route, puis le retour',
	'k516dfc5b' => 'Trois comptages par jour, un message aux parents à 21 h et une ligne d’urgence ouverte jour et nuit.',
